package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.workflow.NfcoreChipseq200Qc;
import static org.jlinalg.cli.NextflowFiles.*;

/** Complete literal labels/tables around the original saved-QC/native-geometry contract. */
final class NfcoreChipseq200QcFiles {
    private NfcoreChipseq200QcFiles() { }
    record Table(List<String> header, List<List<String>> rows) { }
    record Facts(List<String> genes, List<String> samples, int[][] counts, double[] factors,
                 double[][] normalized, double[][] transformed, double[][] scores, double[] sdev,
                 double[] fractions, int[] percentages, double[][] distances) { }
    static Map<String, Object> audit(NfcoreChipseq200Files data, NfcoreChipseq200Peaks.Group group, Path worker, String transform) throws IOException {
        Facts facts = facts(worker, transform); var samples = facts.samples(); var genes = facts.genes();
        if (samples.size() != group.libraries().size() || !new HashSet<>(samples).equals(new HashSet<>(group.libraries()))) throw new IOException("Original DDS and complete antibody-library populations differ; order is retained from the original featureCounts columns");
        Table feature = featureCounts(data.files.output(group.prefix() + ".featureCounts.txt")); var wantedHeader = new ArrayList<>(List.of("Geneid", "Chr", "Start", "End", "Strand", "Length")); for (String sample : samples) wantedHeader.add(sample + ".mLb.clN.sorted.bam");
        if (!feature.header().equals(wantedHeader) || feature.rows().size() != genes.size() || genes.size() != group.consensus().rows().size()) throw new IOException("Complete featureCounts/consensus/DDS labels or dimensions differ");
        for (int g = 0; g < genes.size(); g++) {
            var row = feature.rows().get(g); var interval = group.consensus().rows().get(g);
            if (!row.subList(0, 6).equals(List.of(interval.id(), interval.contig(), Long.toString(interval.start()), Long.toString(interval.end()), "+", Long.toString(interval.end() - interval.start() + 1))) || !row.get(0).equals(genes.get(g))) throw new IOException("Complete original zero-based SAF/featureCounts interval metadata differs; no plus-one repair");
            for (int s = 0; s < samples.size(); s++) if (nonnegative(row.get(s + 6)) != facts.counts()[g][s]) throw new IOException("Complete featureCounts/DDS integer count differs");
        }
        var nativeResult = NfcoreChipseq200Qc.audit(facts.counts(), facts.factors(), facts.normalized(), facts.transformed(), facts.scores(), facts.sdev(), facts.fractions(), facts.distances(), NfcoreChipseq200Qc.Limits.defaults());
        String name = group.prefix().substring(group.prefix().lastIndexOf('/') + 1), qcBase = group.prefix().substring(0, group.prefix().lastIndexOf('/') + 1) + "deseq2/";
        Path pcaPath = data.files.output(qcBase + name + ".pca.vals.txt"), distancesPath = data.files.output(qcBase + name + ".sample.dists.txt");
        Table pca = table(pcaPath, true); if (!pca.header().equals(List.of("sample", "PC1: " + facts.percentages()[0] + "% variance", "PC2: " + facts.percentages()[1] + "% variance")) || pca.rows().size() != samples.size()) throw new IOException("Original complete published PCA schema/variance display differs");
        double[][] published = new double[samples.size()][2]; var sourcePcaOrder = new ArrayList<String>();
        for (var row : pca.rows()) { String sample = row.get(0); int index = samples.indexOf(sample); if (index < 0 || sourcePcaOrder.contains(sample)) throw new IOException("Original published PCA sample is missing, duplicated or renamed"); sourcePcaOrder.add(sample); for (int pc = 0; pc < 2; pc++) published[index][pc] = number(row.get(pc + 1)); }
        NfcoreChipseq200Qc.auditPublishedAxes(facts.transformed(), published, facts.sdev(), NfcoreChipseq200Qc.Limits.defaults());
        Matrix sourceDistances = matrix(table(distancesPath, false), "sample"); requireNames(sourceDistances, samples, samples); compare(sourceDistances.values(), facts.distances(), "Original complete published sample distances");
        for (int s = 0; s < samples.size(); s++) {
            String raw = utf8(bytes(data.files.output(qcBase + "size_factors/" + samples.get(s) + ".txt"), 1024)); if (!raw.endsWith("\n") || raw.substring(0, raw.length() - 1).contains("\n")) throw new IOException("Original per-sample size factor file population differs");
            double observed = number(raw.substring(0, raw.length() - 1)); double expected = facts.factors()[s];
            // Original write(as.numeric(...)) uses seven significant decimal digits.
            double unit = Math.pow(10, Math.floor(Math.log10(Math.abs(expected))) - 6);
            if (Math.abs(observed - expected) > unit * .500001 + 8 * Math.ulp(expected)) throw new IOException("Original size-factor text differs at source seven-significant-digit precision");
        }
        var task = data.task("DESEQ2_QC", group.antibody()); String command = utf8(bytes(data.work(task, ".command.sh"), 1048576));
        int pcaIndex = taskIndex(command, "deseq2_pca"), distanceIndex = taskIndex(command, "deseq2_clustering"); if (pcaIndex != distanceIndex) throw new IOException("Original MultiQC task indices differ");
        multiqc(data, group.antibody(), pcaIndex, "deseq2_pca", pcaPath, data.files.output(qcBase + name + ".pca.vals_mqc.tsv"));
        multiqc(data, group.antibody(), distanceIndex, "deseq2_clustering", distancesPath, data.files.output(qcBase + name + ".sample.dists_mqc.tsv"));
        var report = new LinkedHashMap<String, Object>(); report.put("antibody", group.antibody()); report.put("transform", transform); report.put("design", "~1"); report.put("native_complete_QC", nativeResult.document()); report.put("original_featureCounts_sample_order", samples); report.put("original_published_PCA_row_order", sourcePcaOrder); report.put("PCA_global_sign_and_degenerate_subspace_rotation_allowed", true); report.put("original_MultiQC_task_index", pcaIndex); report.put("source_size_factor_text_significant_digits", 7); report.put("source_SAF_Start_is_unchanged_BED_Start", true); report.put("featureCounts_assignments_independently_recomputed", false); report.put("nonlinear_transform_independently_recomputed", false); report.put("original_MultiQC_heatmap_caption_says_rlog", true); report.put("actual_saved_transform", transform); report.put("scientific_result_admitted", false); return report;
    }
    static Facts facts(Path worker, String transform) throws IOException {
        if (!utf8(bytes(worker.resolve("WORKER_COMPLETED.txt"), 1024)).equals("COMPLETE_ORIGINAL_DESEQ128_QC_FACT_EXPORT_ONLY\n")) throw new IOException("Original complete QC export marker differs");
        Table metadata = table(worker.resolve("model-metadata.tsv"), false); if (!metadata.header().equals(List.of("key", "value"))) throw new IOException("Original QC metadata schema differs"); var fields = new LinkedHashMap<String, String>(); for (var row : metadata.rows()) if (fields.putIfAbsent(row.get(0), row.get(1)) != null) throw new IOException("Duplicate original QC metadata");
        keys(fields, "schema_version", "R_version", "DESeq2_version", "matrixStats_version", "design", "transform", "genes", "samples", "nonlinear_transform_recomputed", "negative_binomial_model_refitted", "original_RData_RDS_facts_identical");
        for (var expected : Map.of("schema_version", "1", "R_version", "4.0.3", "DESeq2_version", "1.28.0", "matrixStats_version", "0.57.0", "design", "~1", "transform", transform, "nonlinear_transform_recomputed", "FALSE", "negative_binomial_model_refitted", "FALSE", "original_RData_RDS_facts_identical", "TRUE").entrySet()) if (!expected.getValue().equals(fields.get(expected.getKey()))) throw new IOException("Original source QC metadata differs: " + expected.getKey());
        Matrix raw = matrix(table(worker.resolve("raw-counts.tsv"), false), "gene"), norm = matrix(table(worker.resolve("normalized-counts.tsv"), false), "gene"), transformed = matrix(table(worker.resolve("stored-transform.tsv"), false), "gene"); requireNames(norm, raw.rows(), raw.columns()); requireNames(transformed, raw.rows(), raw.columns());
        int genes = raw.rows().size(), samples = raw.columns().size(); if (nonnegative(fields.get("genes")) != genes || nonnegative(fields.get("samples")) != samples || genes < 2 || samples < 2 || (long) genes * samples > 20000000L) throw new IOException("Complete saved-QC metadata dimensions/capacity differ");
        int[][] counts = new int[genes][samples]; for (int g = 0; g < genes; g++) for (int s = 0; s < samples; s++) { double value = raw.values()[g][s]; if (value < 0 || value > Integer.MAX_VALUE || value != Math.rint(value)) throw new IOException("Original DDS counts are not exact nonnegative R integers; no rounding"); counts[g][s] = (int) value; }
        Table sampleTable = table(worker.resolve("samples.tsv"), false); if (!sampleTable.header().equals(List.of("sample", "size_factor")) || sampleTable.rows().size() != samples) throw new IOException("Complete QC sample/factor schema differs"); double[] factors = new double[samples]; for (int s = 0; s < samples; s++) { if (!sampleTable.rows().get(s).get(0).equals(raw.columns().get(s))) throw new IOException("Original sample/factor order differs"); factors[s] = number(sampleTable.rows().get(s).get(1)); }
        Matrix scores = matrix(table(worker.resolve("pca-scores.tsv"), false), "sample"); int components = Math.min(samples, genes); var pcNames = new ArrayList<String>(); for (int pc = 1; pc <= components; pc++) pcNames.add("PC" + pc); requireNames(scores, raw.columns(), pcNames);
        Table spectrum = table(worker.resolve("pca-spectrum.tsv"), false); if (!spectrum.header().equals(List.of("PC", "sdev", "fraction", "source_rounded_percent")) || spectrum.rows().size() != components) throw new IOException("Complete original PCA spectrum schema/population differs"); double[] sdev = new double[components], fractions = new double[components]; int[] percentages = new int[components];
        for (int pc = 0; pc < components; pc++) { var row = spectrum.rows().get(pc); if (!row.get(0).equals(pcNames.get(pc))) throw new IOException("Original complete PCA axis names/order differ"); sdev[pc] = number(row.get(1)); fractions[pc] = number(row.get(2)); percentages[pc] = Math.toIntExact(nonnegative(row.get(3))); if (percentages[pc] != Math.rint(100 * fractions[pc])) throw new IOException("Source R rounded PCA percentages differ"); }
        Matrix distances = matrix(table(worker.resolve("source-distances.tsv"), false), "sample"); requireNames(distances, raw.columns(), raw.columns());
        return new Facts(raw.rows(), raw.columns(), counts, factors, norm.values(), transformed.values(), scores.values(), sdev, fractions, percentages, distances.values());
    }
    private record Matrix(List<String> rows, List<String> columns, double[][] values) { }
    private static Matrix matrix(Table table, String firstColumn) throws IOException { if (table.header().size() < 2 || !table.header().get(0).equals(firstColumn) || table.header().size() > 1025 || (long) table.rows().size() * (table.header().size() - 1) > 20000000L) throw new IOException("Complete QC matrix header/capacity differs; no truncated allocation"); var labels = new ArrayList<String>(); var seen = new HashSet<String>(); double[][] values = new double[table.rows().size()][table.header().size() - 1]; for (int r = 0; r < values.length; r++) { var row = table.rows().get(r); if (row.get(0).isEmpty() || !seen.add(row.get(0))) throw new IOException("Empty or duplicate original QC matrix row label"); labels.add(row.get(0)); for (int c = 0; c < values[r].length; c++) values[r][c] = number(row.get(c + 1)); } return new Matrix(List.copyOf(labels), List.copyOf(table.header().subList(1, table.header().size())), values); }
    private static void requireNames(Matrix value, List<String> rows, List<String> columns) throws IOException { if (!value.rows().equals(rows) || !value.columns().equals(columns)) throw new IOException("Complete original QC matrix label/order population differs"); }
    private static void compare(double[][] a, double[][] b, String label) throws IOException { if (a.length != b.length) throw new IOException(label + " dimensions differ"); for (int i = 0; i < a.length; i++) { if (a[i].length != b[i].length) throw new IOException(label + " dimensions differ"); for (int j = 0; j < a[i].length; j++) if (Math.abs(a[i][j] - b[i][j]) > 2e-11 * Math.max(1, Math.max(Math.abs(a[i][j]), Math.abs(b[i][j])))) throw new IOException(label + " cell differs"); } }
    private static int taskIndex(String command, String name) throws IOException { var matcher = java.util.regex.Pattern.compile("(?m)^sed 's/" + name + "/" + name + "_([1-9][0-9]*)/g' ").matcher(command); if (!matcher.find()) throw new IOException("Original QC header task-index command is absent"); int index; try { index = Integer.parseInt(matcher.group(1)); } catch (NumberFormatException bad) { throw new IOException("Original QC task index exceeds capacity", bad); } if (matcher.find()) throw new IOException("Ambiguous original QC task-index command"); return index; }
    private static void multiqc(NfcoreChipseq200Files data, String antibody, int index, String name, Path body, Path actual) throws IOException { String header = utf8(bytes(data.files.inputMember(data.files.alias("workflow") + "/assets/multiqc/" + name + "_header.txt"), 1048576)); String expected = header.replace(name, name + "_" + index).replace("DESeq2 ", antibody + " DESeq2 ") + utf8(bytes(body, 67108864)); if (!expected.equals(utf8(bytes(actual, 67108864)))) throw new IOException("Original complete QC MultiQC source-header replacement/concatenation differs"); }
    private static Table featureCounts(Path path) throws IOException { String raw = utf8(bytes(path, 67108864)); int first = raw.indexOf('\n'); if (first < 0 || !raw.startsWith("# Program:featureCounts v2.0.1; Command:")) throw new IOException("Original featureCounts literal source version/header differs"); return parse(raw.substring(first + 1), false); }
    private static Table table(Path path, boolean quoted) throws IOException { return parse(utf8(bytes(path, 67108864)), quoted); }
    private static Table parse(String value, boolean quoted) throws IOException { var lines = value.lines().toList(); if (lines.isEmpty() || lines.size() > 1000001) throw new IOException("Complete original QC table is absent/oversized"); var rows = new ArrayList<List<String>>(); List<String> header = null; for (String line : lines) { if (line.length() > 1048576 || line.chars().anyMatch(c -> c < 32 && c != '\t')) throw new IOException("Unrepresentable/oversized original QC table row"); var fields = new ArrayList<>(Arrays.asList(line.split("\t", -1))); if (quoted) for (int i = 0; i < fields.size(); i++) fields.set(i, rCell(fields.get(i))); if (header == null) { header = List.copyOf(fields); if (header.stream().anyMatch(String::isEmpty) || new HashSet<>(header).size() != header.size()) throw new IOException("Ambiguous original QC header"); } else { if (fields.size() != header.size()) throw new IOException("Complete original QC row width differs"); rows.add(List.copyOf(fields)); } } return new Table(header, List.copyOf(rows)); }
    private static String rCell(String value) throws IOException { if (!value.startsWith("\"")) return value; if (value.length() < 2 || !value.endsWith("\"")) throw new IOException("Malformed original quoted R cell"); var decoded = new StringBuilder(); for (int i = 1; i < value.length() - 1; i++) { char c = value.charAt(i); if (c == '\\' && i + 1 < value.length() - 1 && value.charAt(i + 1) == '"') { decoded.append('"'); i++; } else { if (c == '"') throw new IOException("Unescaped quote in original R cell"); decoded.append(c); } } return decoded.toString(); }
    private static long nonnegative(String value) throws IOException { try { if (!value.matches("[0-9]+")) throw new NumberFormatException(); return Long.parseLong(value); } catch (NumberFormatException bad) { throw new IOException("Original QC field is not an exact nonnegative bounded integer", bad); } }
    private static double number(String value) throws IOException { try { if (value.length() > 128 || !value.matches("[-+]?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)(?:[eE][-+]?[0-9]+)?")) throw new NumberFormatException(); double n = Double.parseDouble(value); if (!Double.isFinite(n)) throw new NumberFormatException(); return n; } catch (NumberFormatException bad) { throw new IOException("Original QC numeric token is nonfinite/unassessable; no replacement: " + value, bad); } }
}
